-- Slice 5 independent BigInt fixtures, generated by positional integer arithmetic.
-- 7 fixed rank permutations, 8 drop wraps, 30 bowl components, 5 bounds,
-- two exhaustive properties over all 720 ranks, six invalid/NULL checks,
-- and three production-source assertions = 61 native assertions.
BEGIN;
CREATE TEMP TABLE stage02_bowl_assertions(
    test_name text PRIMARY KEY,
    ok boolean NOT NULL CHECK(ok)
);
WITH fixtures(rank1,expected) AS (VALUES
(1,ARRAY[1,2,3,4,5,6]::integer[]),
(2,ARRAY[1,2,3,4,6,5]::integer[]),
(120,ARRAY[1,6,5,4,3,2]::integer[]),
(121,ARRAY[2,1,3,4,5,6]::integer[]),
(360,ARRAY[3,6,5,4,2,1]::integer[]),
(719,ARRAY[6,5,4,3,1,2]::integer[]),
(720,ARRAY[6,5,4,3,2,1]::integer[])
)
INSERT INTO stage02_bowl_assertions(test_name,ok)
SELECT 'rank:'||rank1,
  pastafari_sql_tamil.bowl_order_from_number(rank1)=expected
FROM fixtures;

WITH fixtures(label,drop_value,expected) AS (VALUES
('-721',-721::numeric,ARRAY[6,5,4,3,1,2]::integer[]),
('-720',-720::numeric,ARRAY[6,5,4,3,2,1]::integer[]),
('-1',-1::numeric,ARRAY[6,5,4,3,1,2]::integer[]),
('0',0::numeric,ARRAY[6,5,4,3,2,1]::integer[]),
('1',1::numeric,ARRAY[1,2,3,4,5,6]::integer[]),
('719',719::numeric,ARRAY[6,5,4,3,1,2]::integer[]),
('720',720::numeric,ARRAY[6,5,4,3,2,1]::integer[]),
('721',721::numeric,ARRAY[1,2,3,4,5,6]::integer[])
)
INSERT INTO stage02_bowl_assertions(test_name,ok)
SELECT 'drop:'||label,
  pastafari_sql_tamil.bowl_order_from_drop(drop_value)=expected
FROM fixtures;

WITH cases(label,calculation_day,target_day) AS (VALUES
('same',-15055671::numeric,-15055671::numeric),
('forward',-15055674::numeric,-15055669::numeric),
('reverse',-15055669::numeric,-15055674::numeric),
('large',-15055671::numeric,170141183460469231731687303715869050056::numeric),
('remote-past',-170141183460469231731687303715899161398::numeric,-15055671::numeric)
), got AS MATERIALIZED (
    SELECT label,pastafari_sql_tamil.initial_bowls(
        pastafari_sql_tamil.work_counts(calculation_day,target_day)) AS bowls
    FROM cases
), fixtures(label,bowl_id,expected) AS (VALUES
('same',1,87617::numeric),
('same',2,136163::numeric),
('same',3,289447::numeric),
('same',4,724205::numeric),
('same',5,944789::numeric),
('same',6,1907167::numeric),
('forward',1,102401::numeric),
('forward',2,157611::numeric),
('forward',3,324903::numeric),
('forward',4,786773::numeric),
('forward',5,1024149::numeric),
('forward',6,2030631::numeric),
('reverse',1,101125::numeric),
('reverse',2,156818::numeric),
('reverse',3,324903::numeric),
('reverse',4,788548::numeric),
('reverse',5,1028201::numeric),
('reverse',6,2039190::numeric),
('large',1,88210::numeric),
('large',2,136902::numeric),
('large',3,290524::numeric),
('large',4,725908::numeric),
('large',5,946734::numeric),
('large',6,1909930::numeric),
('remote-past',1,87026::numeric),
('remote-past',2,135426::numeric),
('remote-past',3,288372::numeric),
('remote-past',4,722504::numeric),
('remote-past',5,942846::numeric),
('remote-past',6,1904406::numeric)
)
INSERT INTO stage02_bowl_assertions(test_name,ok)
SELECT 'bowl:'||label||':'||bowl_id,bowls[bowl_id]=expected
FROM fixtures JOIN got USING(label);

WITH cases(label,calculation_day,target_day) AS (VALUES
('same',-15055671::numeric,-15055671::numeric),
('forward',-15055674::numeric,-15055669::numeric),
('reverse',-15055669::numeric,-15055674::numeric),
('large',-15055671::numeric,170141183460469231731687303715869050056::numeric),
('remote-past',-170141183460469231731687303715899161398::numeric,-15055671::numeric)
), got AS MATERIALIZED (
    SELECT label,pastafari_sql_tamil.initial_bowls(
        pastafari_sql_tamil.work_counts(calculation_day,target_day)) AS bowls
    FROM cases
)
INSERT INTO stage02_bowl_assertions(test_name,ok)
SELECT 'bounds:'||label,
  coalesce(array_length(bowls,1),0)=6 AND
  (SELECT bool_and(x BETWEEN 1 AND pastafari_sql_tamil.save_modulus())
   FROM unnest(bowls) AS u(x))
FROM got;

WITH orders AS MATERIALIZED (
    SELECT pastafari_sql_tamil.bowl_order_from_number(r) AS ord
    FROM generate_series(1,720) AS s(r)
)
INSERT INTO stage02_bowl_assertions(test_name,ok)
SELECT 'all-720-unique',count(DISTINCT ord)=720 FROM orders
UNION ALL
SELECT 'all-720-valid',
  bool_and(coalesce(array_length(ord,1),0)=6
    AND (SELECT array_agg(x ORDER BY x) FROM unnest(ord) AS u(x))
         =ARRAY[1,2,3,4,5,6]::integer[])
FROM orders;

INSERT INTO stage02_bowl_assertions(test_name,ok)
SELECT 'invalid-rank-0',pastafari_sql_tamil.bowl_order_from_number(0) IS NULL
UNION ALL SELECT 'invalid-rank-721',pastafari_sql_tamil.bowl_order_from_number(721) IS NULL
UNION ALL SELECT 'null-rank',pastafari_sql_tamil.bowl_order_from_number(NULL::integer) IS NULL
UNION ALL SELECT 'null-drop',pastafari_sql_tamil.bowl_order_from_drop(NULL::numeric) IS NULL
UNION ALL SELECT 'null-bowls',pastafari_sql_tamil.initial_bowls(NULL::pastafari_sql_tamil.work_counts) IS NULL
UNION ALL SELECT 'fractional-drop',pastafari_sql_tamil.bowl_order_from_drop(1.5::numeric) IS NULL
UNION ALL SELECT 'pure-production',
    (SELECT count(*)=0 FROM pg_proc p
       JOIN pg_namespace n ON n.oid=p.pronamespace
       WHERE n.nspname='pastafari_sql_tamil'
         AND p.proname IN ('bowl_factorial','bowl_order_from_number','bowl_order_from_drop','initial_bowls')
         AND position('pastafari_sql_tamil_test' in pg_get_functiondef(p.oid))>0)
UNION ALL SELECT 'functions-sql',
    (SELECT count(*)=4 FROM pg_proc p
       JOIN pg_namespace n ON n.oid=p.pronamespace
       JOIN pg_language l ON l.oid=p.prolang
       WHERE n.nspname='pastafari_sql_tamil'
         AND p.proname IN ('bowl_factorial','bowl_order_from_number','bowl_order_from_drop','initial_bowls')
         AND l.lanname='sql')
UNION ALL SELECT 'functions-immutable',
    (SELECT count(*)=4 FROM pg_proc p
       JOIN pg_namespace n ON n.oid=p.pronamespace
       WHERE n.nspname='pastafari_sql_tamil'
         AND p.proname IN ('bowl_factorial','bowl_order_from_number','bowl_order_from_drop','initial_bowls')
         AND p.provolatile='i');

SELECT 'slice5 bowl native assertions' AS status,count(*) AS assertion_count
FROM stage02_bowl_assertions;
COMMIT;
